function checkOutputs({records,minimumItems,recordIdField}) {
  const minimum=Number(minimumItems);
  if(!Number.isSafeInteger(minimum)||minimum<0||minimum>1000000000)throw new Error('minimumItems must be a non-negative integer, at most 1000000000.');
  const field=String(recordIdField||'').trim();
  if(!field)throw new Error('Set recordIdField to the field identifying a completed output.');
  if(!Array.isArray(records)||records.some(record=>!record||typeof record!=='object'||Array.isArray(record)))throw new Error('records must be an array of objects.');
  const rows=records.filter(record=>Object.keys(record).length>0);
  const keys=new Set();let invalidItems=0;
  for(const row of rows){
    const value=row[field];
    const valid=(typeof value==='string'&&value.trim().length>0)||(typeof value==='number'&&Number.isFinite(value));
    if(!valid){invalidItems++;continue;}
    keys.add(String(value).trim());
  }
  const items=keys.size;
  const duplicateItems=rows.length-invalidItems-items;
  return {checkPassed:items>=minimum&&invalidItems===0,checkStatus:invalidItems?'invalid_output':items<minimum?'below_minimum':'healthy',minimumItems:minimum,items,invalidItems,duplicateItems};
}

const config=$('Configure check').first().json;
return [{json:checkOutputs({records:$input.all().map(item=>item.json),minimumItems:config.minimumItems,recordIdField:config.recordIdField})}];
